class VisibleTextExtractor(HTMLParser):
    """Extract visible text from a string with HTML tags."""

    def __init__(self):
        ...

    def handle_data(self, data):
        ...

    def extract_visible_text(self, html: str) -> str:
        ...

def __init__(self):
        super().__init__()
        self.text_parts = []

def extract_visible_text(self, html: str) -> str:
