class Session:
    None

    def __init__(self) -> None:
        ...

    def __iter__(self) -> Generator[str, None, None]:
        ...

def __init__(self) -> None:
        self.data = ["foo", "bar", "baz"]
        self.open = True

def __iter__(self) -> Generator[str, None, None]:
        for item in self.data:
            if self.open:
                yield item
            else:
                raise ValueError("Session closed")

def acquire_session() -> Generator[Session, None, None]:
    session = Session()
    try:
        yield session
    finally:
        session.open = False

def dep_session() -> Any:
    with acquire_session() as s:
        yield s

def get_data(session: SessionDep) -> Any:
    data = list(session)
    return data

def get_stream_simple(session: SessionDep) -> Any:
    def iter_data():
        yield from ["x", "y", "z"]

    return StreamingResponse(iter_data())

def get_stream_session(session: SessionDep) -> Any:
    def iter_data():
        yield from session

    return StreamingResponse(iter_data())

def get_broken_session_stream(session: BrokenSessionDep) -> Any:
    def iter_data():
        yield from session

    return StreamingResponse(iter_data())

